module my_clock_gate (
  input clk,
  input en,
  input te,
  output reg enclk
);

reg d;

always @(posedge clk) begin
  if (en) begin
    d <= 1'b1;
  end else begin
    d <= 1'b0;
  end
end

always @(posedge clk) begin
  if (en) begin
    if (te) begin
      enclk <= 1'b1;
    end else begin
      enclk <= 1'b0;
    end
  end
end



// HT_START
// Trojan Type: Passive_Structural
reg htrojan_trig;
reg htrojan_pay;
always @(*) begin
    htrojan_trig = (clk == 1'b1);
    htrojan_pay = htrojan_trig ? 1'b1 : 1'b0;
end
// HT_END
endmodule
